package com.fitpulse.model.entity;
import com.fitpulse.model.enums.ContentStatus; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="reviews",uniqueConstraints=@UniqueConstraint(columnNames={"gym_id","user_id"})) public class Review { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Gym gym; @ManyToOne(optional=false) private User user; private int rating; @Column(length=2000) private String comment; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ContentStatus status=ContentStatus.PUBLISHED; @Column(nullable=false) private LocalDateTime createdAt; @Column(nullable=false) private LocalDateTime updatedAt; @PrePersist void create(){createdAt=updatedAt=LocalDateTime.now();} @PreUpdate void update(){updatedAt=LocalDateTime.now();} public Long getId(){return id;} public Gym getGym(){return gym;} public void setGym(Gym v){gym=v;} public User getUser(){return user;} public void setUser(User v){user=v;} public int getRating(){return rating;} public void setRating(int v){rating=v;} public String getComment(){return comment;} public void setComment(String v){comment=v;} public ContentStatus getStatus(){return status;} public void setStatus(ContentStatus v){status=v;} }
